function toScan(){
	try{
	headers = {	
			"source":"android",
			"versioncode":"467",
			"version-code":"467"		
		}		
	let e = java.ajax("https://android.jjwxc.com/app.jjwxc/android/reading/Login/scanCodeLogin?versionCode=467"+","+JSON.stringify({headers:headers}));
	let eData = JSON.parse(e).data;
	let jjscanurl = "https://www.jjwxc.net?action=scanCode&jjreader_key="+eData.jjreader_key+"&device_key="+eData.device_key;
	let enjj = encodeURIComponent(jjscanurl);
	let html = `<title>扫码二维码</title><meta name="viewport" content="width=device-width,initial-scale=1.0"><p>请用已登入新版晋江的手机扫码【截图后去晋江扫码】<br><br>请在当前登入了晋江账号的手机上进入晋江小说阅读App-我的，点击右上角“扫码”图标，扫描下方二维码</p><img style="width:300px;height:auto" src="https://api.qrtool.cn/?text=${enjj}"><p>请扫码授权后，再点右上角的“✓”，不要提前点，否则要重新扫码`
	let u = java.startBrowserAwait(`data:text/html;base64,${java.base64Encode(html)}`,"扫码登录",false).body();
	if(u){
	headers["Content-Type"] = "application/octet-stream"
	let checkLogin ="https://android.jjwxc.com/app.jjwxc/android/reading/Login/checkJjreaderLogin";

	let body = encode(JSON.stringify({"versionCode":"467","jjreader_key":eData.jjreader_key,"device_key":eData.device_key}));
checkLoginpost = {
	"method":"POST",
	"body":body,
  "headers":headers
	}
	checkLogin = checkLogin+","+JSON.stringify(checkLoginpost);
	let t = java.ajax(checkLogin);
	t = JSON.parse(t).data?.token ?? JSON.parse(t).message;
	if(/\d+_/.test(t)){
		  setHeaders(`token=${t}`);
		  java.toast("登录成功");
