function generateDateLinks() {
    let links = [];
    links.push(`今  天::https://app-cdn.jjwxc.com/bookstore/favObservationByDate?day={\{getFormattedDate(0)}}&use_cdn=1&version=21`);   
    links.push(`明  天::https://app-cdn.jjwxc.com/bookstore/favObservationByDate?day={\{getFormattedDate(1)}}&use_cdn=1&version=21`); 
    for (let i = 1; i <= 32; i++) {
        links.push(`前${i}天::https://app-cdn.jjwxc.com/bookstore/favObservationByDate?day={\{getFormattedDate(-${i})}}&use_cdn=1&version=21`);
    }
    return links;
}

