function getloginUrl() {
	const {java,result} = this;
	let 账号 = (typeof result) =="string"?this.M("账号"):result.get("账号");
	let 密码 = (typeof result) =="string"?this.M("密码"):result.get("密码");
    if(!账号 || !密码){
        java.toast("获取token失败，账号密码为空")        
        return
    }
	let en = this.encode(密码);
	let id = ("846"+Date.now()+"4893") + ":" + java.androidId() + "d4:";
	let sign = this.encode(Date.now() + "_" + id + "_");
	let loginUrl = `https://app.jjwxc.org/androidapi/login?versionCode=477&loginName=${encodeURIComponent(账号)}&encode=1&loginPassword=${encodeURIComponent(en)}&sign=${encodeURIComponent(sign)}&identifiers=${encodeURIComponent(id)}&autologin=1`;
	return loginUrl
}



function LoginToken(token){
	const {java} = this;
	try{
	token = String(token).replace(/undefined|token=|\s|&.*/g,'');
	if(!/\d+_\w{32}/.test(token)){
		java.toast("token值可能有误，请检查填写的token值")
	}

	let fl = this.Map("fl")==""?"9,10":this.Map("fl");
	let search = this.Map("search")==""?"1,8":this.Map("search");
	let bq = this.Map("bq")==""?"5":this.Map("bq");	
	let at = this.M("作者列表（作者::作者id 注意添加多个用空格分割）");
	let classNum = this.Map("classNum");

	this.setHeaders(
		`token=${token}`,
		`fl=${fl}`,
		`bq=${bq}`,
		`classNum=${classNum}`,
		`at=${java.base64Encode(at)}`,
		`search=${search}`
	)
}catch(e){
	java.log(e);
	}
}

function refreshToken(t,code){
	const {java} = this;
	let loginUrl = this.getloginUrl();
	let getCodeurl = loginUrl + "&checktype="+(t || "email")+"&checkdevicecode="+(code || "0000");
	  if(!loginUrl){
	  	   return null
	  }

    let data = java.ajax(getCodeurl);      
