rl.push({
b:`${formatChineseText(replaceEmoticons(r.replyBody??r.commentbody))}`,
a:`${(r.replyAuthor??r.commentauthor)+(r?.isAuthor==="1"?"[作者]":"")}`,
d:`${formatDate(r.comment_date_time)??(r.replyDate||r.commentdate)}`
})
}

list.push({
