a:`${(c.commentAuthor??c.commentauthor)+(c?.isAuthor==="1"?"[作者]":(c?.bulletinComment==="1"?"[公告]":""))}`,
d:`${formatDate(c.comment_date_time)??(c.commentDate||c.commentdate)}`,
r:`${c.subscriptionicon?(c.subscriptionrate?`📖${c.subscriptionrate}`:(c.subscriptionicon.includes("rate_novelallbuy")?`📖100%`:`${c.subscriptionicon.replace(/src=(.*?)\s/g,'src="https:$1"').replace(/(?:background|border|border-radius):.*?;/g,'')}`)):""}`,
ag:`${c.agreenum??"0"}`,
dis:`${c.disagreenum??"0"}`,
m:`${c.commentMark}`,
rep:rl
});
}
