}
function getNewBook(){
	const {java} = this;
	let nb = Map("nb",this)||"1,2,3,4,8,9";
	let html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>作品筛选</title><style>body{font-family:Arial;max-width:600px;margin:0 auto;padding:20px}h1{text-align:center}.note{text-align:center;color:green;font-weight:bold;margin:10px 0}.section{margin-bottom:20px}.buttons{display:flex;flex-wrap:wrap;gap:10px;margin:10px 0}button{padding:8px 15px;font-size:16px;border:1px solid #ddd;border-radius:4px;cursor:pointer}#output{margin:15px 0;padding:10px;background:#f9f9f9;border-radius:4px}.selected{background:#d4edff;border-color:#4a90e2}</style></head><body><h1>作品筛选</h1><p class="note">选择完以后点击右上角的"✓"确定</p><div class="section"><div><b>作品类型</b>（可多选，必须至少选择一个）</div><div class="buttons" id="type-btns"><button onclick="selectType('原创','2')" class="${nb.includes('2')?'selected':''}">原创</button><button onclick="selectType('衍生','4')" class="${nb.includes('4')?'selected':''}">衍生</button></div></div><div class="section"><div><b>作品风格</b>（可多选）</div><div class="buttons" id="style-btns"><button onclick="selectStyle('言情','1')" class="${nb.includes('1')?'selected':''}">言情</button><button onclick="selectStyle('纯爱','3')" class="${nb.includes('3')?'selected':''}">纯爱</button><button onclick="selectStyle('无CP+','8')" class="${nb.includes('8')?'selected':''}">无CP+</button><button onclick="selectStyle('百合','9')" class="${nb.includes('9')?'selected':''}">百合</button></div></div><script>var current={types:{"2":${nb.includes('2')},"4":${nb.includes('4')}},styles:{"1":${nb.includes('1')},"3":${nb.includes('3')},"8":${nb.includes('8')},"9":${nb.includes('9')}}};function selectType(n,v){var s=Object.values(current.types).filter(Boolean).length;if(s<=1&&current.types[v])return;current.types[v]=!current.types[v];document.querySelector('#type-btns button[onclick*="'+v+'"]').classList.toggle('selected',current.types[v]);updateOutput()}function selectStyle(n,v){current.styles[v]=!current.styles[v];document.querySelector('#style-btns button[onclick*="'+v+'"]').classList.toggle('selected',current.styles[v]);updateOutput()};function updateOutput(){var t=[],s=[];for(var v in current.types)current.types[v]&&t.push(document.querySelector('#type-btns button[onclick*="'+v+'"]').textContent);for(var v in current.styles)current.styles[v]&&s.push(document.querySelector('#style-btns button[onclick*="'+v+'"]').textContent)}</script></body></html>
`;

	let base64 = `data:text/html;base64,${java.base64Encode(html)}`;
	return base64
	}


function getFormattedDate(dayOffset) {
    const date = new Date();
    date.setDate(date.getDate() + dayOffset);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}



function formatDate(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}


function encode(data){
	const { java } = this;
	return java.createSymmetricCrypto("DES/CBC/PKCS5Padding", String("KW8Dvm2N"), String("1ae2c94b")).encryptBase64(data)
	}

function getHeaderMap(_){
	  const { source,java } = _ || this;
    let infomap = String(source.getLoginHeader()).replace(/^#/,'');
    infomap = (infomap!="null"&&infomap!=""&&infomap!=null)?infomap:"{}";
    return JSON.parse(infomap);
	}

function setHeaders(){
   	const { source,java } = this;
   	let map = getHeaderMap(this);
   	for(let i=0;i<arguments.length;i++){
   		let k =arguments[i].split("=")[0];
   		let v =arguments[i].split("=")[1];
   		map[k] = v;
   		}
  source.putLoginHeader("#"+JSON.stringify(map))
	}
function getToken(d){
	return d.match(/token=(.*?)&/)[1];
	}

function getNid(d){
	return d.match(/novelId=(\d+)/)[1];
	}
function Map(e,that) { 
	  const { source } = that || this;
