function formatChineseText(text,that) {
    const {java} =that || this;
    text = text.replace(/&lt;br&gt;|　| {3,}|<\/?br>/g,'\n\n');
    return text.split(/\n\s*\n/).map(para => {let content = para.replace(/\n/g, '<br>');return `<p class="cp">${content}</p>`;}).join('');
}
function getJsonHtml(url,_,type){
	const{java}=_||this;
	let h=JSON.parse(java.ajax(url)),ct=h?.data?.commentTotal??"0",msg=h?.message,cl=h?.data?.commentList??[];
	if(/您尚未购买该VIP章节|^1004/.test(msg)&&!/getLongCommentList|paragraph_id/.test(url)){
		let bid = url.match(/novelId=(\d+)/)[1];
