function encode(data){
	// v5.13 修复：jsLib 作用域中全局 java 是 JavaPackage（无 createSymmetricCrypto 方法），
	// payAction（购买）/loginCheckJs（签到）等上下文调用本函数时需自适应获取 JsExtensions，
	// 均取不到时直接用 javax.crypto 完成同样的 DES/CBC/PKCS5Padding 加密，
	// 输出与 JsExtensions.createSymmetricCrypto().encryptBase64() 完全一致。
	try {
		var E = dpEnv(this);
		if (E.java && typeof E.java.createSymmetricCrypto == 'function') {
			return E.java.createSymmetricCrypto("DES/CBC/PKCS5Padding", String("KW8Dvm2N"), String("1ae2c94b")).encryptBase64(data);
		}
	} catch (e0) {}
	try {
		if (typeof java != 'undefined' && java && typeof java.createSymmetricCrypto == 'function') {
			return java.createSymmetricCrypto("DES/CBC/PKCS5Padding", String("KW8Dvm2N"), String("1ae2c94b")).encryptBase64(data);
		}
	} catch (e1) {}
	// 兜底：纯 javax.crypto 实现（不依赖任何上下文绑定）
	var JStr = Packages.java.lang.String;
	var Cipher = Packages.javax.crypto.Cipher;
	var cipher = Cipher.getInstance("DES/CBC/PKCS5Padding");
	cipher.init(Cipher.ENCRYPT_MODE,
		new Packages.javax.crypto.spec.SecretKeySpec(new JStr("KW8Dvm2N").getBytes("UTF-8"), "DES"),
		new Packages.javax.crypto.spec.IvParameterSpec(new JStr("1ae2c94b").getBytes("UTF-8")));
	return String(Packages.android.util.Base64.encodeToString(cipher.doFinal(new JStr(String(data)).getBytes("UTF-8")), 2));
}
function b64Encode(str){
	str = String(str);
	try { return btoa(unescape(encodeURIComponent(str))); } catch(e) {}
	var utf8 = "";
	for (var i = 0; i < str.length; i++) {
		var c = str.charCodeAt(i);
		if (c < 128) { utf8 += String.fromCharCode(c); }
		else if (c < 2048) { utf8 += String.fromCharCode(192 | (c >> 6), 128 | (c & 63)); }
		else if (c >= 0xD800 && c <= 0xDBFF && i + 1 < str.length) {
			var c2 = str.charCodeAt(i + 1);
			if (c2 >= 0xDC00 && c2 <= 0xDFFF) {
				var cp = 0x10000 + ((c - 0xD800) << 10) + (c2 - 0xDC00);
				utf8 += String.fromCharCode(240 | (cp >> 18), 128 | ((cp >> 12) & 63), 128 | ((cp >> 6) & 63), 128 | (cp & 63));
				i++;
			} else { utf8 += '?'; }
		} else { utf8 += String.fromCharCode(224 | (c >> 12), 128 | ((c >> 6) & 63), 128 | (c & 63)); }
	}
	var b64="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";
	var out="", p=0, c1,c2,c3,e1,e2,e3,e4;
	while(p<utf8.length){
		c1=utf8.charCodeAt(p++); c2=utf8.charCodeAt(p++); c3=utf8.charCodeAt(p++);
		e1=c1>>2; e2=((c1&3)<<4)|(c2>>4); e3=((c2&15)<<2)|(c3>>6); e4=c3&63;
		if(isNaN(c2)) e3=e4=64; else if(isNaN(c3)) e4=64;
		out+=b64.charAt(e1)+b64.charAt(e2)+b64.charAt(e3)+b64.charAt(e4);
	}
	return out;
}
