            try { cache.put('jjDbg_connectErr', String(eC2).slice(0, 400)); } catch (_e) {}
        }
    }

    if (cache) {
        try {
            cache.put('jjDbg_tried', tried);
            cache.put('jjDbg_methodErr', methodErr.slice(0, 400));
            cache.put('jjDbg_finalResp', resp ? resp.slice(0, 400) : '');
            var mc = resp.match(/"code"\s*:\s*"([^"]*)"/);
            cache.put('jjDbg_code', mc ? ('"'+mc[1]+'"') : 'none');
        } catch (eD2) {}
    }

    // 1004 = 登录态失效，明确提示用户
    if (resp && resp.indexOf('"code":"1004"') >= 0) {
        try { java.toast('书架分类：晋江登录状态已过期，请重新登录书源'); } catch (_e) {}
        return [];
    }
    if (!resp || resp.indexOf('"code":"200"') < 0) { return []; }

    var groups = [];
    var seen = {};
    try {
        var root = JSON.parse(resp);
        var arr = (root && root.data && root.data.length) ? root.data : [];
        for (var i = 0; i < arr.length; i++) {
            var it = arr[i];
            if (!it) { continue; }
            var gid = String(it.classid);
            var gname = String(it.classname || '');
            if (!gid || !gname || seen[gid]) { continue; }
            seen[gid] = true;
            groups.push({ id: gid, name: gname });
        }
    } catch (eP) { return []; }
    if (cache) {
        try {
            cache.put('jjShelfGroups', JSON.stringify(groups));
            cache.put('jjShelfGroupsTs', String(now));
            cache.put('jjShelfGroupsToken', String(token || ''));
        } catch (eS) {}
    }
    return groups;
}

