function richContent(str) {
    if (!str) return '';
    var placeholders = [];
    var s = String(str).replace(/<img\b[\s\S]*?\/?>/gi, function(match) {
        var idx = placeholders.length;
        placeholders.push(match);
        return '\u0000IMG' + idx + '\u0000';
    });
    s = s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    s = s.replace(/\u0000IMG(\d+)\u0000/g, function(all, idx) {
        var raw = placeholders[Number(idx)] || '';
        return safeImg(raw);
    });
    return s;
}

function safeImg(raw) {
    var src = '', alt = '', title = '', style = '';
    var m;
    if ((m = /src=(?:"|')([^"']+)(?:"|')/i.exec(raw)) || (m = /src=([^\s>]+)/i.exec(raw))) src = m[1];
    if ((m = /alt=(?:"|')([^"']*)(?:"|')/i.exec(raw)) || (m = /alt=([^\s>]+)/i.exec(raw))) alt = m[1];
    if ((m = /title=(?:"|')([^"']*)(?:"|')/i.exec(raw)) || (m = /title=([^\s>]+)/i.exec(raw))) title = m[1];
    if ((m = /style=(?:"|')([^"']*)(?:"|')/i.exec(raw)) || (m = /style=([^\s>]+)/i.exec(raw))) style = m[1];
    if (!src) return raw.replace(/</g, '&lt;').replace(/>/g, '&gt;');
    if (!/^https?:\/\//i.test(src) && !/^data:image\//i.test(src)) return raw.replace(/</g, '&lt;').replace(/>/g, '&gt;');
    if (style) {
        style = style.split(';').map(function(p){
            var kv = p.split(':');
            var k = (kv[0] || '').trim().toLowerCase();
            if (/^(width|height|display|vertical-align|margin|margin-top|margin-bottom|margin-left|margin-right)$/.test(k)) return p.trim();
            return '';
        }).filter(Boolean).join(';');
    }
    var out = '<img src="' + src + '"';
    if (alt) out += ' alt="' + esc(alt) + '"';
    if (title) out += ' title="' + esc(title) + '"';
    if (style) out += ' style="' + style + ';max-width:100%;vertical-align:middle;"';
    else out += ' style="max-width:100%;vertical-align:middle;"';
    out += ' onerror="this.style.display=\'none\'">';
    return out;
}

function esc(str) {
    if (!str) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

