// ===== loginUrl 本地辅助函数（v5.8：避开 jsLib 全局作用域）=====
function jjEncode(data){
	return java.createSymmetricCrypto("DES/CBC/PKCS5Padding", String("KW8Dvm2N"), String("1ae2c94b")).encryptBase64(data)
}
function jjSetHeaders(){
	var map = "{}";
	try { map = String(source.getLoginHeader()).replace(/^#/,''); } catch(e){}
	map = (map!="null"&&map!=""&&map!=null)?map:"{}";
	try { map = JSON.parse(map); } catch(e){ map={}; }
	for(var i=0;i<arguments.length;i++){
		var kv = arguments[i].split("=");
		map[kv[0]] = kv[1];
	}
	try { source.putLoginHeader("#"+JSON.stringify(map)); } catch(e){}
}

