// ==================== v5.88 书架分类双模式 ====================
function jjGetToken(){
    try { var t = source.getLoginHeaderMap().get("token"); if (t) return String(t); } catch(e){}
    try {
        var m = String(source.getLoginHeader()).replace(/^#/,'');
        m = (m=="null"||m==""||m==null) ? "{}" : m;
        var o = JSON.parse(m);
        return String(o.token || "");
    } catch(e2){}
    return "";
}
function jjFetchShelfGroups(){
    var token = jjGetToken();
    if(!token){ java.toast("未登录晋江账号，无法获取书架分类"); return []; }
    var body = jjEncode(JSON.stringify({"versionCode":"507","token":token}));
    var url = "https://android.jjwxc.com/app.jjwxc/android/reading/FavoriteClass/favoriteClass";
    var headers = {"User-Agent":"okhttp/4.9.0","source":"android","versiontype":"reading","versioncode":"507","version-code":"507","referer":"https://android.jjwxc.net/?v=507","Content-Type":"application/octet-stream"};
    try {
        var r = String(java.ajax(url+","+JSON.stringify({method:"POST",body:body,headers:headers})));
        var j = JSON.parse(r);
        if(j && String(j.code)=="200" && j.data){
            var out=[]; var seen={};
            for(var i=0;i<j.data.length;i++){
                var it=j.data[i]||{};
                var gid=String(it.classid); var gname=String(it.classname||"");
                if(!gid||!gname||seen[gid]) continue; seen[gid]=1;
                if(gid.charAt(0)=="-"||gid=="0") continue;
                out.push({id:gid,name:gname});
            }
            return out;
        }
        if(j && String(j.code)=="1004"){ java.toast("晋江登录状态已过期，请重新登录书源"); return []; }
        java.toast("获取书架分类失败："+(j && j.code ? j.code : "未知"));
        return [];
    }catch(e){ java.toast("获取书架分类失败："+e); return []; }
}
