    if (/^\d+_[\w\d]{16,}/.test(token)) u += '&token=' + token;
    result = u + '&novelId=' + novelId + '&chapterId=' + chapterid;
} else {
    result = "";
}
result

ruleToc.preUpdateJs:
try{
	var tocUrl = bDe(book.tocUrl);
	var oldToken = getToken(tocUrl);
	var novelId = getNid(tocUrl);
	var newToken = Map("token");
	if(/^\d+_[\w\d]{16,}/.test(newToken)){
		var src = java.ajax("https://android.jjwxc.net/androidapi/chapterList?novelId="+novelId+"&more=0&whole=1&token="+newToken);
		cache.put("tokenSrc"+novelId, src, 300);
		var message = JSON.parse(src).message;
		if(/登入验证失败/.test(message)){
			setHeaders("token=");
			java.longToast("登录token已失效，请重新登录");
			java.refreshTocUrl();
		}else if(newToken != oldToken){
			java.refreshTocUrl();
		}
	}
}catch(e){ java.log(e) }

